#undef LIST_PARM//#pragma warning(push)#pragma warning(disable: 4101)#define LIST_PARM(BaseClass,Class,DimV) \  static Class _W;\  typedef Class _Class;\  static SVarInfo VarInfo[DimV];\  static int kVarInfo = 0;\  void BaseClass::SetParmList( )\  {\    if( !kVarInfo ) \      BaseClass::InitParm();\    ClassVarInfo = VarInfo;\    kClassVarInfo = kVarInfo;\    initW( W, &_W );\    pClass_FullW = ((BYTE*)static_cast<Class*>(W)) + sizeof(CBase);\    L_Class_FullW = sizeof (Class) - sizeof(CBase);\  }//#pragma warning(pop)static SVarInfo::eFlags s_defFlag = SVarInfo::efVar;template<class T, class V>SVarInfo* InitInfo( eVarType type, T &_W, V *var, LPCSTR pszVarName, V def){  ASS( *pszVarName )  *var = def;  ASS( kVarInfo < _countof(VarInfo) );  SVarInfo * pV = &(VarInfo[kVarInfo++]);  pV->sVar =(DWORD)((BYTE*)var - (BYTE*)&_W);  pV->VarName = pszVarName;  pV->Type = type;#ifdef _DEBUG  ASS( sizeof(V) < USHRT_MAX );#endif  pV->varSize = sizeof(V);  pV->flags |= s_defFlag;  return pV;}template<class T, class V>SVarInfo* InitInfo( eVarType type, T &_W, V *var, LPCSTR pszVarName){  ASS( *pszVarName )  ASS( kVarInfo < _countof(VarInfo) );  SVarInfo * pV = &(VarInfo[kVarInfo++]);  pV->sVar =(DWORD)((BYTE*)var - (BYTE*)&_W);  pV->VarName = pszVarName;  pV->Type = type;#ifdef _DEBUG  ASS( sizeof(V) < USHRT_MAX );#endif  pV->varSize = sizeof(V);  pV->flags |= s_defFlag;  return pV;}template<class T, class V>SVarInfo* InitInfoEnum( eVarType type, T &_W, V *var, LPCSTR pszVarName, BYTE def, LPCSTR penumVals){  ASS( *pszVarName )  *var = def;  ASS( kVarInfo < _countof(VarInfo) );  SVarInfo * pV = &(VarInfo[kVarInfo++]);  pV->sVar =(DWORD)((BYTE*)var - (BYTE*)&_W);  pV->VarName = pszVarName;  pV->Type = type;  pV->flags |= SVarInfo::efEnum;  pV->pszEnumVals = penumVals;#ifdef _DEBUG  ASS( sizeof(V) < USHRT_MAX );#endif  pV->varSize = sizeof(V);  pV->flags |= s_defFlag;  return pV;}#undef REAL#define REAL(Var,Def,Desc) InitInfo( evtFloat, _W, &_W.Var, #Var, (float)Def);#undef DBLE#define DBLE(Var,Def,Desc) InitInfo( evtDouble, _W, &_W.Var, #Var, (double)Def);#undef DBLE2#define DBLE2(Var,VarName,Def,Desc) InitInfo( evtDouble, _W, &_W.Var, #Var, (double)Def);#undef INT2#define INT2(Var,Def,Desc) InitInfo( evtInt2, _W, &_W.Var, #Var, (short)Def);#undef INT4#define INT4(Var,Def,Desc) InitInfo( evtInt4, _W, &_W.Var, #Var, (int)Def);#undef Boolean#define Boolean(Var,Def,Desc) InitInfo( evtBool, _W, &_W.Var, #Var, (bool)Def);#undef STRING#define STRING(Var,Len,Comm) \{SVarInfo* pV = InitInfo( evtString, _W, &_W.Var, #Var); pV->varSize = Len; }#undef STRING_2#define STRING_2(Var,VarName,Len,Comm) \{SVarInfo* pV = InitInfo( evtString, _W, &_W.Var, #Var); pV->varSize = Len; }#undef ENUMERATION#define ENUMERATION(Var,Desc,...) InitInfoEnum( evtByte, _W, &_W.Var, #Var, _Class::_##Var::Def, #__VA_ARGS__ );#define LIST_ALGO(ALGO,BaseClass,DimV )\  static SVarInfo VarInfo##ALGO[DimV];\  static int kVarInfo##ALGO = 0;